def transform(grid):
    from collections import Counter
    h=len(grid); out=[row[:] for row in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            # These are the isolated marker colors in this task.
            if v not in (0,1,5,8): continue
            near=[]
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<len(grid[rr]): near.append(grid[rr][cc])
            counts=Counter(x for x in near if x not in (v,bg))
            out[r][c]=counts.most_common(1)[0][0] if counts and counts.most_common(1)[0][1]>=2 else bg
    return out
